-- ================================================================================
-- 1. CORE TABLE: DIVISION
-- ================================================================================
CREATE TABLE `division` (
    `divisi_id` INT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ================================================================================
-- 2. CORE TABLE: USERS
-- ================================================================================
CREATE TABLE `users` (
    `user_id` INT AUTO_INCREMENT PRIMARY KEY,
    `userID` VARCHAR(255) NOT NULL UNIQUE,
    `role` ENUM('USER', 'ADMIN', 'SUPERADMIN') DEFAULT 'USER',
    `gender` ENUM('MALE', 'FEMALE', 'OTHER') DEFAULT 'MALE',
    `divisi_id` INT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted_at` DATETIME NULL,
    CONSTRAINT `fk_users_division` FOREIGN KEY (`divisi_id`) REFERENCES `division`(`divisi_id`) ON DELETE SET NULL,
    INDEX `idx_userID` (`userID`),
    INDEX `idx_role` (`role`),
    INDEX `idx_deleted` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ================================================================================
-- 3. CORE TABLE: AUTH
-- ================================================================================
CREATE TABLE `auth` (
    `auth_id` INT AUTO_INCREMENT PRIMARY KEY,
    `userID` VARCHAR(255) NOT NULL UNIQUE,
    `hash_password` VARCHAR(255) NOT NULL,
    `refresh_token` VARCHAR(500) NULL,
    `reset_password_token` VARCHAR(500) NULL,
    `user_id` INT NOT NULL UNIQUE,
    CONSTRAINT `fk_auth_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
    INDEX `idx_userID` (`userID`),
    INDEX `idx_user_id` (`user_id`),
    INDEX `idx_refresh_token` (`refresh_token`(100)),
    INDEX `idx_reset_token` (`reset_password_token`(100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ================================================================================
-- 4. CORE TABLE: RISK APPETITE STATEMENT (RAS)
-- ================================================================================
CREATE TABLE `risk_appetite_statement` (
    `id` INT PRIMARY KEY AUTO_INCREMENT,
    `year` INT NOT NULL,
    `groupId` VARCHAR(100),
    `riskCategory` VARCHAR(100) NOT NULL,
    `no` INT,
    `parameter` TEXT NOT NULL,
    `statement` TEXT,
    `formulasi` TEXT,
    `riskStance` VARCHAR(50) DEFAULT 'Moderat',
    `unitType` VARCHAR(20) DEFAULT 'PERCENTAGE',
    `dataTypeExplanation` TEXT,
    `notes` TEXT,
    `rkapTarget` VARCHAR(100),
    `rasLimit` VARCHAR(100),
    `hasNumeratorDenominator` BOOLEAN DEFAULT FALSE,
    `numeratorLabel` VARCHAR(100),
    `denominatorLabel` VARCHAR(100),
    `monthlyValues` JSON,
    `tindakLanjut` JSON,
    `createdAt` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updatedAt` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_year` (`year`),
    INDEX `idx_riskCategory` (`riskCategory`),
    INDEX `idx_groupId` (`groupId`),
    INDEX `idx_year_risk` (`year`, `riskCategory`) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ================================================================================
-- 5. CORE TABLE: AUDIT LOG
-- ================================================================================
CREATE TABLE `audit_log` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT DEFAULT NULL,
  `action` ENUM('CREATE', 'UPDATE', 'DELETE', 'VIEW', 'EXPORT', 'LOGIN', 'LOGOUT') NOT NULL,
  `module` ENUM(
    'INVESTASI', 'PASAR', 'LIKUIDITAS', 'OPERASIONAL', 'HUKUM', 'STRATEJIK', 'KEPATUHAN', 'REPUTASI', 'USER_MANAGEMENT', 'SYSTEM', 'RAS',
    'HUKUM_OJK', 'INVESTASI_OJK', 'KEPATUHAN_OJK', 'KONSENTRASI_OJK', 'KREDIT_PRODUK_OJK', 'LIKUIDITAS_PRODUK_OJK', 'OPERASIONAL_OJK', 'PASAR_PRODUK_OJK', 'PERMODALAN_OJK', 'RENTABILITAS_OJK', 'REPUTASI_OJK', 'STRATEGIS_OJK', 'TATAKELOLA_OJK'
  ) NOT NULL,
  `description` TEXT NOT NULL,
  `endpoint` TEXT DEFAULT NULL,
  `ip_address` VARCHAR(45) DEFAULT NULL,
  `is_success` TINYINT(1) NOT NULL DEFAULT 1,
  `timestamp` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `metadata` JSON DEFAULT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_timestamp` (`timestamp`),
  INDEX `idx_module` (`module`),
  INDEX `idx_action` (`action`),
  INDEX `idx_user_id` (`user_id`),
  INDEX `idx_action_module` (`action`, `module`),
  INDEX `idx_module_action_timestamp` (`module`, `action`, `timestamp`),
  CONSTRAINT `fk_audit_log_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ================================================================================
-- 6. CORE TABLE: NOTIFICATIONS
-- ================================================================================
CREATE TABLE `notifications` (
  `notification_id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NULL,
  `type` ENUM('info', 'success', 'warning', 'error', 'system') DEFAULT 'info',
  `title` VARCHAR(255) NOT NULL,
  `message` TEXT NOT NULL,
  `read` BOOLEAN DEFAULT FALSE,
  `metadata` JSON NULL,
  `category` VARCHAR(255) NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `expires_at` DATETIME NULL,
  PRIMARY KEY (`notification_id`),
  INDEX `idx_user_id` (`user_id`),
  INDEX `idx_created_at` (`created_at`),
  CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ================================================================================
-- 7. OJK MODULES MASTER
-- ================================================================================
CREATE TABLE `ojk_modules` (
    `id` VARCHAR(50) NOT NULL,
    `label` VARCHAR(100) NOT NULL,
    `description` TEXT NULL,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `order_index` INT NOT NULL DEFAULT 0,
    `created_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

