-- ================================================================================
-- OJK MODULE: PASAR PRODUK
-- ================================================================================
CREATE TABLE `inherent_references_pasar_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `type` VARCHAR(50) NOT NULL,
    `key` VARCHAR(50) NOT NULL,
    `label` VARCHAR(100) NOT NULL,
    `color` VARCHAR(20) NULL,
    `description` TEXT NULL,
    `is_active` BOOLEAN DEFAULT TRUE,
    `order` INT DEFAULT 0,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_pasar_produk_ref_type` (`type`),
    INDEX `idx_pasar_produk_ref_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pasar_produk_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `year` INT NOT NULL,
    `quarter` INT NOT NULL,
    `is_active` BOOLEAN DEFAULT TRUE,
    `summary` JSON NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `created_by` VARCHAR(255) NULL,
    `updated_by` VARCHAR(255) NULL,
    `version` VARCHAR(50) DEFAULT '1.0.0',
    `is_locked` BOOLEAN DEFAULT FALSE,
    `locked_at` TIMESTAMP NULL,
    `locked_by` VARCHAR(255) NULL,
    `notes` TEXT NULL,
    UNIQUE INDEX `uniq_pasar_produk_year_quarter` (`year`, `quarter`),
    INDEX `idx_pasar_produk_year_quarter` (`year`, `quarter`),
    INDEX `idx_pasar_produk_is_active_year_quarter` (`is_active`, `year`, `quarter`),
    INDEX `idx_pasar_produk_created_at` (`created_at`),
    CHECK (`year` >= 2000 AND `year` <= 2100),
    CHECK (`quarter` BETWEEN 1 AND 4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pasar_produk_parameters_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nomor` VARCHAR(50) NULL,
    `judul` VARCHAR(255) NOT NULL,
    `bobot` DECIMAL(10, 2) NOT NULL,
    `kategori` JSON NULL,
    `pasar_produk_ojk_id` INT NOT NULL,
    `order_index` INT DEFAULT 0,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (`pasar_produk_ojk_id`) REFERENCES `pasar_produk_ojk`(`id`) ON DELETE CASCADE,
    INDEX `idx_pasar_produk_param_id_nomor` (`pasar_produk_ojk_id`, `nomor`),
    INDEX `idx_pasar_produk_param_id_order` (`pasar_produk_ojk_id`, `order_index`),
    INDEX `idx_pasar_produk_param_id` (`pasar_produk_ojk_id`),
    CHECK (`bobot` >= 0 AND `bobot` <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pasar_produk_nilai_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nomor` VARCHAR(50) NULL,
    `judul` JSON NULL,
    `bobot` DECIMAL(10, 2) NOT NULL,
    `portofolio` VARCHAR(255) NULL,
    `keterangan` TEXT NULL,
    `riskindikator` JSON NULL,
    `sumber_risiko` TEXT NULL,
    `dampak` TEXT NULL,
    `parameter_id` INT NOT NULL,
    `order_index` INT DEFAULT 0,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (`parameter_id`) REFERENCES `pasar_produk_parameters_ojk`(`id`) ON DELETE CASCADE,
    INDEX `idx_pasar_produk_nilai_param_id_nomor` (`parameter_id`, `nomor`),
    INDEX `idx_pasar_produk_nilai_param_id` (`parameter_id`),
    INDEX `idx_pasar_produk_nilai_param_id_order` (`parameter_id`, `order_index`),
    CHECK (`bobot` >= 0 AND `bobot` <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `kpmr_pasar_produk_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `year` INT NOT NULL,
    `quarter` INT NOT NULL,
    `is_active` BOOLEAN DEFAULT TRUE,
    `summary` JSON NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `created_by` VARCHAR(255) NULL,
    `updated_by` VARCHAR(255) NULL,
    `version` VARCHAR(50) DEFAULT '1.0.0',
    `is_locked` BOOLEAN DEFAULT FALSE,
    `locked_at` TIMESTAMP NULL,
    `locked_by` VARCHAR(255) NULL,
    `notes` TEXT NULL,
    INDEX `idx_kpmr_pasar_produk_year_quarter` (`year`, `quarter`),
    INDEX `idx_kpmr_pasar_produk_is_active_year_quarter` (`is_active`, `year`, `quarter`),
    INDEX `idx_kpmr_pasar_produk_created_at` (`created_at`),
    CHECK (`year` >= 2000 AND `year` <= 2100),
    CHECK (`quarter` BETWEEN 1 AND 4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `kpmr_aspek_pasar_ojk` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nomor` VARCHAR(50) NULL,
    `judul` VARCHAR(255) NOT NULL,
    `bobot` DECIMAL(10, 2) DEFAULT 0.00,
    `deskripsi` TEXT NULL,
    `kpmr_ojk_id` INT NOT NULL,
    `order_index` INT DEFAULT 0,
    `average_score` DECIMAL(10, 2) NULL,
