-- ================================================================================
-- DATABASE VIEW: risk_profile_repository_ojk_view
-- ================================================================================
CREATE OR REPLACE VIEW `risk_profile_repository_ojk_view` AS
    SELECT 
      'PASAR' AS "moduleType", p.id AS "id", h.year AS "year", h.quarter AS "quarter", p.parameter_id AS "sectionId", pp.nomor AS "no", pp.judul AS "sectionLabel", pp.bobot AS "bobotSection",
      p.nomor AS "subNo", JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.text')) AS "indikator", p.bobot AS "bobotIndikator", p.sumber_risiko AS "sumberRisiko", p.dampak AS "dampak",
      JSON_UNQUOTE(JSON_EXTRACT(p.riskindikator, '$.low')) AS "low", JSON_UNQUOTE(JSON_EXTRACT(p.riskindikator, '$.lowToModerate')) AS "lowToModerate",
      JSON_UNQUOTE(JSON_EXTRACT(p.riskindikator, '$.moderate')) AS "moderate", JSON_UNQUOTE(JSON_EXTRACT(p.riskindikator, '$.moderateToHigh')) AS "moderateToHigh",
      JSON_UNQUOTE(JSON_EXTRACT(p.riskindikator, '$.high')) AS "high",
      JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.type')) AS "mode", JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.formula')) AS "formula",
      (COALESCE(JSON_EXTRACT(p.judul, '$.percent'), 'false') = 'true') AS "isPercent",
      JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.pembilang')) AS "pembilangLabel", 
      JSON_UNQUOTE(COALESCE(JSON_EXTRACT(p.judul, '$.valuePembilang'), JSON_EXTRACT(p.judul, '$.value'))) AS "pembilangValue",
      JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.penyebut')) AS "penyebutLabel", 
      JSON_UNQUOTE(JSON_EXTRACT(p.judul, '$.valuePenyebut')) AS "penyebutValue",
      NULL AS "hasil", NULL AS "hasilText", 0 AS "peringkat", 0 AS "weighted", p.keterangan AS "keterangan", 
      COALESCE(h.is_locked, FALSE) AS "isValidated", p.created_at AS "createdAt", p.updated_at AS "updatedAt", pp.judul AS "parameter", NULL AS "sectionDescription"
    FROM `pasar_produk_nilai_ojk` p
    LEFT JOIN `pasar_produk_parameters_ojk` pp ON p.parameter_id = pp.id
    LEFT JOIN `pasar_produk_ojk` h ON pp.`pasar_produk_ojk_id` = h.id
    UNION ALL
    SELECT 
